package local.thinksmart.chatgpt;
import org.junit.*;
import java.net.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import static org.junit.Assert.*;
public class LoopbackPolicyServerTest {
 private LoopbackPolicyServer server; private java.security.KeyPair key; private int count; private String captured;
 @Before public void start() throws Exception {key=java.security.KeyPairGenerator.getInstance("RSA").generateKeyPair();server=new LoopbackPolicyServer(new LoopbackPolicyServer.Backend(){public long setupUntil(){return 1234;}public String signPolicy(String nonce,boolean locked,long until){try{java.security.Signature sig=java.security.Signature.getInstance("SHA256withRSA");sig.initSign(key.getPrivate());sig.update(PolicySignature.canonical(nonce,locked,until));return java.util.Base64.getEncoder().encodeToString(sig.sign());}catch(Exception e){throw new RuntimeException(e);}}public void blocked(String kind,String scheme,String host){count++;captured=kind+":"+scheme+":"+host;}},0);server.start();}
 @After public void stop(){server.close();}
 private String request(String method,String path,String headers,String body)throws Exception{try(Socket s=new Socket("127.0.0.1",server.port())){s.setSoTimeout(4000);String wire=method+" "+path+" HTTP/1.1\r\n"+(headers.contains("Host:")?"":"Host: 127.0.0.1:"+server.port()+"\r\n")+(headers.contains("X-ThinkSmart-Bridge:")?"":"X-ThinkSmart-Bridge: 1\r\n")+headers+"Content-Length: "+body.getBytes(StandardCharsets.UTF_8).length+"\r\n\r\n"+body;s.getOutputStream().write(wire.getBytes(StandardCharsets.UTF_8));ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[512];int n;while((n=s.getInputStream().read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8");}}
 @Test public void signedPolicyAndNonce()throws Exception{String nonce="0123456789abcdef0123456789abcdef";assertTrue(request("GET","/policy","","").contains("400 Response"));assertTrue(request("GET","/policy","X-ThinkSmart-Nonce: wrong\r\n","").contains("400 Response"));String r=request("GET","/policy","X-ThinkSmart-Nonce: "+nonce+"\r\n","");String signature=r.split("\"signature\":\"")[1].split("\"")[0];java.security.Signature verifier=java.security.Signature.getInstance("SHA256withRSA");verifier.initVerify(key.getPublic());verifier.update(PolicySignature.canonical(nonce,false,1234));assertTrue(verifier.verify(java.util.Base64.getDecoder().decode(signature)));verifier.initVerify(key.getPublic());verifier.update(PolicySignature.canonical(nonce,true,1234));assertFalse(verifier.verify(java.util.Base64.getDecoder().decode(signature)));}
 @Test public void policyAndBoundary()throws Exception{String r=request("GET","/policy","X-ThinkSmart-Nonce: 0123456789abcdef0123456789abcdef\r\n","");assertTrue(r.contains("200 Response"));assertTrue(r.contains("\"childLocked\":false"));assertTrue(r.contains("\"setupUntil\":1234"));assertFalse(r.toLowerCase().contains("access-control-allow-origin"));assertTrue(request("GET","/policy?x=1","","").contains("400 Response"));assertTrue(request("GET","/policy","Origin: http://127.0.0.1\r\n","").contains("403 Response"));assertTrue(request("GET","/policy","Sec-Fetch-Site: same-origin\r\n","").contains("403 Response"));assertTrue(request("GET","/policy","Host: evil\r\n","").contains("403 Response"));assertTrue(request("GET","/policy","X-ThinkSmart-Bridge: 2\r\n","").contains("403 Response"));assertTrue(request("POST","/policy","","").contains("405 Response"));assertTrue(request("GET","/nope","","").contains("404 Response"));}
 @Test public void localSchemeCanHaveOnlyEmptyHost()throws Exception{String type="Content-Type: application/x-www-form-urlencoded\r\n";assertTrue(request("POST","/event",type,"kind=navigation&scheme=https&host=").contains("400 Response"));assertTrue(request("POST","/event",type,"kind=navigation&scheme=about&host=example.com").contains("400 Response"));assertTrue(request("POST","/event",type,"kind=navigation&scheme=about&host=").contains("200 Response"));assertEquals("navigation:about:",captured);}
 @Test public void eventsValidateAndLimit()throws Exception{String type="Content-Type: application/x-www-form-urlencoded\r\n";assertTrue(request("POST","/event",type,"kind=navigation&scheme=https&host=example.com%2Fsecret").contains("400 Response"));assertTrue(request("POST","/event",type,"kind=navigation&scheme=https&host=x&host=y").contains("400 Response"));assertTrue(request("POST","/event",type,"kind=navigation&scheme=https&host=x&extra=y").contains("400 Response"));assertTrue(request("POST","/event",type,"kind=navigation&scheme=https&host="+new String(new char[1100]).replace('\0','x')).contains("400 Response"));assertTrue(request("POST","/event","","kind=navigation&scheme=https&host=x").contains("415 Response"));assertTrue(request("POST","/event",type,"kind=subframe&scheme=https&host=example.com").contains("200 Response"));assertEquals("subframe:https:example.com",captured);assertTrue(request("POST","/event",type,"kind=navigation&scheme=https&host=x").contains("429 Response"));assertEquals(1,count);}
}
